message:
Now-building on this code-I want to add parallax using react spring. On scroll bring up the films section in a way that it looks like the films section is coming up from the bottom and covering up the hero section. Keep the already established functionality of the code, just add parallax.

```tsx
import Navbar from "@/components/Navbar";
import Hero from "@/components/home/Hero";
import Films from "@/components/home/Films";
import Featured from "@/components/home/Featured";
import About from "@/components/home/About";
import Footer from "@/components/Footer";

const Index = () => {
  return (
    <main className="w-full flex flex-col items-center">
      <Navbar />
      <Hero />
      <div className="relative w-full">
        <div className="hidden md:block absolute inset-0 bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-secondary-muted via-transparent via-20% to-transparent pointer-events-none"></div>
        <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_top_left,_var(--tw-gradient-stops))] from-primary-muted via-transparent via-45% to-transparent pointer-events-none"></div>
        <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_bottom_left,_var(--tw-gradient-stops))] from-accent-more-muted via-transparent via-30% to-transparent pointer-events-none"></div>
        <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_bottom_right,_var(--tw-gradient-stops))] from-primary-more-muted via-transparent via-40% to-transparent pointer-events-none"></div>

        <div className="relative flex flex-col items-center">
          <Films />
          <Featured />
          <About />
        </div>
      </div>

      <Footer />
    </main>
  );
};

export default Index;
```

